style.css:
/* Minty Bloom — Roblox */
:root {
  /* swap these colors if you want */
  --my-mint: #B9E8C5;
  --my-light-mint: #E5F5E8;
  --my-sage: #75B889;
  --my-dark-sage: #426B4D;
}

/* soft mint page background */
body {
  background-color: var(--my-light-mint) !important;
  color: var(--my-dark-sage) !important;
}

/* links and accents */
a {
  color: var(--my-sage) !important;
}

/* buttons */
button {
  background-color: var(--my-mint) !important;
  color: var(--my-dark-sage) !important;
  border-color: var(--my-sage) !important;
}

/* softer images */
img {
  border-radius: 10px !important;
}
